#!/usr/bin/env python3
"""Print the world-fill AI content ledger section (stdout). Usage: python3 -I scripts/gen-world-fill-ledger.py <cr-api-unity root>"""
import glob, json, os, sys
g = os.path.join(sys.argv[1], "Assets/CR/Game/")
T = set(os.path.basename(f)[:-5] for f in glob.glob(g + "Story/Content/Text/*.json"))
D = "2026-10-22"
S = "AI draft — replace before launch"
used = set()
out = ["## World fill content (cr-api-unity `feature/world-fill`, 2026-10-22)", "",
 "Generated by AI from the world-fill plan: 154 side quests in 15 packets, their NPC dialogue, readables and barks, and the gimmick notes of the optional dungeons. One row per unit; none of it has been through a human. Overview tables: [World Fill Content](?page=content/02-world-fill). Packet and dungeon tooling: [Side Content Packets](?page=unity/46-side-content-packets), [Dungeon Scaffold](?page=unity/47-dungeon-scaffold).", "",
 "| Item (what was generated) | Where it's used | Where to update it | Created | Updated | Status |", "|---|---|---|---|---|---|"]
for f in sorted(glob.glob(g + "Story/Content/Side/[AS]*.json")):
    p = json.load(open(f, encoding="utf-8")); k = p["packet"]
    dl = []
    for n in p["npcs"]:
        for c in sorted({n.get("dialogue", ""), n.get("dialogue", "") + "-bark", n["key"].replace("npc-", "dialogue-")}):
            if c and c in T and c not in used: dl.append(c); used.add(c)
    rk = [r["key"] if isinstance(r, dict) else r for r in p["readables"]]
    rf = [r for r in rk if r in T and r not in used]; used.update(rf)
    out.append("| Packet %s manifest text: %d quest names, descriptions and objective text, %d NPC names, trainer and location names (`Side/%s.json`) | Journal, tracker, NPC nameplates, side region %s | `Assets/CR/Game/Story/Content/Side/%s.json` then `cr_side_author` · Studio Quests / NPCs tabs | %s | %s | %s |" % (k, len(p["quests"]), len(p["npcs"]), k, ", ".join(sorted({q["region"] for q in p["quests"]})), k, D, D, S))
    out.append("| Packet %s dialogue, %d files: %s | Side NPC conversations and barks of packet %s | `Assets/CR/Game/Story/Content/Text/<file>.json` (staging) then `Assets/CR/Content/Defs/Dialogues/` · Studio Dialogues tab | %s | %s | %s |" % (k, len(dl), ", ".join("`%s`" % d for d in dl), k, D, D, S))
    out.append("| Packet %s readables, %d files: %s | Signs, notes and ledgers read in the world, packet %s | `Assets/CR/Game/Story/Content/Text/<file>.json` then `Assets/CR/Content/Defs/Readables/` · Studio Readables tab | %s | %s | %s |" % (k, len(rf), ", ".join("`%s`" % d for d in rf), k, D, D, S))
for f in sorted(glob.glob(g + "OpenWorld/Data/Dungeons/*.json")):
    if os.path.basename(f).startswith("_"): continue
    d = json.load(open(f, encoding="utf-8"))
    out.append("| Dungeon `%s` \"%s\" gimmick note and event text: \"%s\" | Optional dungeon in region %s | `Assets/CR/Game/OpenWorld/Data/Dungeons/%s.json` then `cr_dungeon_scaffold` | %s | %s | %s |" % (d["key"], d["name"], d["gimmick"].replace("|", "/"), d["region"], d["key"], D, D, S))
print("\n".join(out)); print()
